from engine import Engine
from story import STORY

RULES = "Enter a choice number, or 'save' / 'quit'."


def show_status(eng):
    items = ", ".join(eng.state["items"]) or "none"
    print(f"[trust: {eng.state['vars'].get('trust', 0)} | items: {items}]")


def main():
    eng = Engine(STORY)
    print("=" * 62)
    print("HOLLOW VALE - an interactive tale")
    print("=" * 62)
    answer = input("Load saved game? (y/N): ").strip().lower()
    if answer == "y" and eng.load():
        print("Save loaded.")
    else:
        print("Starting anew.")
    while True:
        node_id = eng.state["node"]
        node = STORY[node_id]
        print("\n" + "-" * 62)
        print(eng.render(node["text"]))
        if node.get("ending"):
            print("\n*** ENDING: " + node.get("title", "The End") + " ***")
            show_status(eng)
            print("Thanks for playing Hollow Vale.")
            break
        opts = eng.options(node_id)
        if not opts:
            if node.get("next"):
                input("\n[Enter to continue] ")
                eng.state["node"] = node["next"]
                continue
            print("\n*** The tale ends here. ***")
            break
        show_status(eng)
        for i, choice in enumerate(opts, 1):
            print(f"  {i}. {choice['text']}")
        raw = input("> ").strip().lower()
        if raw == "save":
            eng.save()
            print("Game saved.")
        elif raw == "quit":
            eng.save()
            print("Game saved. Farewell.")
            break
        elif raw.isdigit() and 1 <= int(raw) <= len(opts):
            eng.choose(int(raw) - 1)
        else:
            print(RULES)


if __name__ == "__main__":
    main()
