"""Branching-narrative engine: state tracking, conditional checks, effects, save/load."""
import json
import os

SAVE_FILE = "savegame.json"


class Engine:
    def __init__(self, story, start=None):
        self.story = story
        self.start = start or next(iter(story))
        self.new_game()

    def new_game(self):
        self.state = {"node": self.start, "vars": {"trust": 0}, "items": [], "log": []}

    def context(self):
        ctx = dict(self.state["vars"])
        ctx["items"] = self.state["items"]
        return ctx

    def check(self, condition):
        """Evaluate a condition string against current state (vars + items)."""
        if not condition:
            return True
        try:
            return bool(eval(condition, {"__builtins__": {}}, self.context()))
        except Exception:
            return False

    def apply(self, effects):
        """Apply a choice's effects: add/set variables, add/remove items."""
        if not effects:
            return
        for key, delta in effects.get("vars_add", {}).items():
            self.state["vars"][key] = self.state["vars"].get(key, 0) + delta
        for key, value in effects.get("vars_set", {}).items():
            self.state["vars"][key] = value
        for item in effects.get("items", []):
            if item not in self.state["items"]:
                self.state["items"].append(item)
        for item in effects.get("remove_items", []):
            if item in self.state["items"]:
                self.state["items"].remove(item)

    def render(self, text):
        """Interpolate state variables into narrative text."""
        try:
            return text.format(**self.context())
        except Exception:
            return text

    def options(self, node_id):
        """Choices of a node whose conditions currently pass."""
        node = self.story[node_id]
        return [c for c in node.get("choices", []) if self.check(c.get("condition"))]

    def choose(self, index):
        node_id = self.state["node"]
        choice = self.options(node_id)[index]
        self.apply(choice.get("effects"))
        self.state["log"].append(choice["text"])
        self.state["node"] = choice["next"]

    def save(self, path=SAVE_FILE):
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(self.state, fh)

    def load(self, path=SAVE_FILE):
        if not os.path.exists(path):
            return False
        with open(path, encoding="utf-8") as fh:
            self.state = json.load(fh)
        return True
